kubectl get crd databases.example.com      # the type definition
kubectl get databases.example.com -A       # instances (CRs) of that type
apiVersion: example.com/v1
kind: Database
metadata: {name: orders}
spec: {engine: postgres, size: 20Gi}

for {
  obj := <-informer.Events()          // watch via API server
  desired := obj.Spec.Replicas
  actual := countPods(obj)
  if actual < desired { createPod(obj) }
  if actual > desired { deletePod(obj) }
}

func (r *DatabaseReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    var db examplev1.Database
    if err := r.Get(ctx, req.NamespacedName, &db); err != nil { ... }
    // observe actual state, create/update children, update status
    return ctrl.Result{RequeueAfter: 5 * time.Minute}, nil
}

informer := factory.Example().V1().Databases().Informer()
informer.AddEventHandler(cache.ResourceEventHandlerFuncs{
    AddFunc:    func(o interface{}) { queue.Add(keyOf(o)) },
    UpdateFunc: func(_, n interface{}) { queue.Add(keyOf(n)) },
})
// LIST once, then WATCH; workers pop keys and call reconcile

// idempotent: look before you create
var sts appsv1.StatefulSet
err := r.Get(ctx, types.NamespacedName{Name: db.Name, Namespace: db.Namespace}, &sts)
if apierrors.IsNotFound(err) {
    return r.Create(ctx, buildStatefulSet(&db))
}
return r.Update(ctx, mergeDesired(&sts, &db))   // safe to run 100 times

