make manifests   # regenerates config/rbac/role.yaml

if err := external.Provision(ctx, db); err != nil {
    return ctrl.Result{}, err              // re-enqueued with exponential backoff
}
if !external.Ready(ctx, db) {
    return ctrl.Result{RequeueAfter: 30 * time.Second}, nil   // expected wait
}
return ctrl.Result{}, nil
